import 'jest';
import { LocalStorage } from '../../src';

describe('LocalStorage', () => {
    let setItemSpy: jest.SpyInstance;
    let getItemSpy: jest.SpyInstance;
    let removeItemSpy: jest.SpyInstance;
    let clearSpy: jest.SpyInstance;

    beforeEach(() => {
        setItemSpy = jest.spyOn(Storage.prototype, 'setItem');
        getItemSpy = jest.spyOn(Storage.prototype, 'getItem');
        removeItemSpy = jest.spyOn(Storage.prototype, 'removeItem');
        clearSpy = jest.spyOn(Storage.prototype, 'clear');
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    describe('is set to available', () => {
        beforeEach(() => {
            jest.spyOn(LocalStorage, 'isAvailable', 'get').mockReturnValue(true);
        });

        afterEach(() => {
            jest.clearAllMocks();
        });

        it('will set items using native local storage', () => {
            LocalStorage.setItem('test', 'value');
            expect(setItemSpy).toBeCalledTimes(1);
        });

        it('will get items using native local storage', () => {
            LocalStorage.getItem('test');
            expect(getItemSpy).toBeCalledTimes(1);
        });

        it('will remove items using native local storage', () => {
            LocalStorage.removeItem('test');
            expect(removeItemSpy).toBeCalledTimes(1);
        });

        it('will clear using native local storage', () => {
            LocalStorage.clear();
            expect(clearSpy).toBeCalledTimes(1);
        });
    });

    describe('is set to unavailable', () => {
        beforeEach(() => {
            jest.spyOn(LocalStorage, 'isAvailable', 'get').mockReturnValue(false);
        });

        afterEach(() => {
            jest.clearAllMocks();
        });

        it('will set items using in memory fallback', () => {
            LocalStorage.setItem('test', 'value');
            expect(setItemSpy).toBeCalledTimes(0);
        });

        it('will get items using in memory fallback', () => {
            LocalStorage.getItem('test');
            expect(getItemSpy).toBeCalledTimes(0);
        });

        it('will remove items using in memory fallback', () => {
            LocalStorage.removeItem('test');
            expect(removeItemSpy).toBeCalledTimes(0);
        });

        it('will clear using in memory fallback', () => {
            LocalStorage.clear();
            expect(clearSpy).toBeCalledTimes(0);
        });
    });
});